.app-panels [data-panel] {
  height: 100%;
  min-height: 0;
  min-height: 100vh;
}

.app-single-pane {
  flex: 1;
  width: 100%;
  height: 100%;
  min-height: 0;
  min-height: 100vh;
}

.sidebar-toggle-btn {
  position: absolute;
  top: 5.5px;
  left: 82px;
  z-index: 32;
  width: 24px;
  height: 22px;
  border: none;
  background: transparent;
  color: rgba(112, 119, 128, 0.9);
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.sidebar-toggle-btn svg {
  width: 16px;
  height: 16px;
}

.sidebar-toggle-btn:hover {
  background: rgba(120, 128, 138, 0.12);
  color: rgba(82, 89, 98, 0.95);
}

.sidebar-toggle-btn:active {
  background: rgba(120, 128, 138, 0.18);
}

.app-resize-handle {
  position: relative;
  width: 0;
  background: transparent;
  z-index: 6;
  cursor: col-resize;
}

.app-resize-handle::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
  background: color-mix(in srgb, var(--ui-border) 12%, transparent);
