import type { CSSProperties, Dispatch, ReactNode, SetStateAction } from "react";
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/shared/ui/resizable";

type DesktopShellProps = {
  theme: "light" | "dark";
  appStyle: CSSProperties;
  sidebarCollapsed: boolean;
  onToggleSidebar: () => void;
  showMiddlePane: boolean;
  twoPaneLayout: Record<string, number>;
  setTwoPaneLayout: Dispatch<SetStateAction<Record<string, number>>>;
  threePaneLayout: Record<string, number>;
  setThreePaneLayout: Dispatch<SetStateAction<Record<string, number>>>;
  leftPane: ReactNode;
  middlePane: ReactNode;
  rightPane: ReactNode;
};

export function DesktopShell({
  theme,
  appStyle,
  sidebarCollapsed,
  onToggleSidebar,
  showMiddlePane,
  twoPaneLayout,
  setTwoPaneLayout,
  threePaneLayout,
  setThreePaneLayout,
  leftPane,
  middlePane,
  rightPane,
}: DesktopShellProps) {
  return (
    <div className={`app theme-${theme}${sidebarCollapsed ? " sidebar-collapsed" : ""}`} style={appStyle}>
      {!sidebarCollapsed ? (
        <button
          type="button"
          className="sidebar-toggle-btn"
          aria-label="Hide sidebar"
          onClick={onToggleSidebar}
        >
          <svg viewBox="0 0 16 16" aria-hidden>
            <rect
              x="1.25"
              y="1.75"
              width="13.5"
              height="12.5"
              rx="3.25"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.25"
            />
            <path
              d="M5.8 2.9v10.2"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.25"
            />
          </svg>
        </button>
      ) : null}

      {sidebarCollapsed ? (
        <div className="app-single-pane">{rightPane}</div>
      ) : !showMiddlePane ? (
        <ResizablePanelGroup
          orientation="horizontal"
          className="app-panels"
          defaultLayout={twoPaneLayout}
          onLayoutChanged={(layout) => setTwoPaneLayout(layout)}
        >
          <ResizablePanel
            id="nav"
            defaultSize="29%"
            minSize="18%"
            maxSize="44%"
            className="min-w-0 h-full min-h-0"
          >
            {leftPane}
          </ResizablePanel>
          <ResizableHandle className="app-resize-handle" />
          <ResizablePanel
            id="content"
            defaultSize="71%"
            minSize="35%"
            className="min-w-0 h-full min-h-0"
          >
            {rightPane}
          </ResizablePanel>
        </ResizablePanelGroup>
      ) : (
        <ResizablePanelGroup
          orientation="horizontal"
          className="app-panels"
          defaultLayout={threePaneLayout}
          onLayoutChanged={(layout) => setThreePaneLayout(layout)}
        >
          <ResizablePanel
            id="nav"
            defaultSize="22%"
            minSize="16%"
            maxSize="34%"
            className="min-w-0 h-full min-h-0"
          >
            {leftPane}
          </ResizablePanel>
          <ResizableHandle className="app-resize-handle" />
          <ResizablePanel
            id="middle"
            defaultSize="25%"
  min-height: 100vh;
}

.app-panels [data-panel] {
  height: 100%;
  min-height: 0;
  min-height: 100vh;
}

.app-single-pane {
  flex: 1;
  width: 100%;
  height: 100%;
  min-height: 0;
  min-height: 100vh;
}

.sidebar-toggle-btn {
  position: absolute;
  top: 5.5px;
  left: 82px;
  z-index: 32;
  width: 24px;
  height: 22px;
  border: none;
  background: transparent;
  color: rgba(112, 119, 128, 0.9);
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.sidebar-toggle-btn svg {
  width: 16px;
  height: 16px;
}

.sidebar-toggle-btn:hover {
  background: rgba(120, 128, 138, 0.12);
  color: rgba(82, 89, 98, 0.95);
}

.sidebar-toggle-btn:active {
  background: rgba(120, 128, 138, 0.18);
}

.app-resize-handle {
  position: relative;
  width: 0;
  background: transparent;
  z-index: 6;
  cursor: col-resize;
}

.app-resize-handle::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
  background: color-mix(in srgb, var(--ui-border) 12%, transparent);
  pointer-events: none;
   let the native macOS overlay titlebar show through as a hard 3-4px band at
   the top edge, since nothing was left to diffuse it. */

.app.theme-dark .tiptap-content pre {
  background: rgba(255, 255, 255, 0.09);
}

.app.theme-dark .tiptap-content code {
  background: rgba(255, 255, 255, 0.1);
}

.app.theme-dark .empty {
  color: #a0a9b7;
}

.app.theme-dark .tiptap-content p.is-editor-empty:first-child::before {
  color: #a0a9b7;
}

@media (max-width: 1000px) {
  .pane-drag-region {
    display: none;
  }

  .sidebar-toggle-btn {
    display: none;
  }

  .app.theme-dark .tiptap-content {
    padding-top: 24px;
  }

}

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
}

.editor-top-row {
  min-height: calc(12px + var(--left-panels-drag-height));
  padding: calc(8px + var(--left-panels-drag-height)) clamp(22px, 5vw, 64px) 0;
  align-items: flex-start;
}

