                documentKey={loadedNotePath}
                markdown={editorMarkdown}
                onChange={handleEditorChange}
              />
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <SettingsDetailPane
      activeSection={activeSettingsSection}
      onOpenTrash={onOpenTrash}
      onPaneClick={() => focusNoScroll(rightPaneRef.current)}
    />
  );
}

